function opportunities(){document.getElementById('view').innerHTML=`<div class="page">${intro('GLOBAL OPPORTUNITY EXPLORER','Search opportunities across countries and fields.','Explore scholarships, competitions, research, fellowships, internships, exchanges, summer schools, conferences, grants and youth programs. Filter by the details that affect eligibility.')}
 <div class="notice info"><b>Catalogue status:</b> The catalogue includes a starter directory of global programs and official-source discovery leads. Every seed record is pending review unless explicitly marked closed. Cycle dates, fees and eligibility are not assumed. Add verified opportunity datasets through CSV or JSON; imported records remain local in this prototype.</div>
 <form id="filters" class="catalogue-filters"><div class="field search-field"><label>Search</label><input class="input" name="q" placeholder="Opportunity, provider, field or keyword"></div><div class="filter-grid"><div class="field"><label>Category</label><select class="select" name="cat"><option>All categories</option>${['Scholarship','Competition','Research','Fellowship','Internship','Apprenticeship','Volunteering','Youth Program','Conference','Summer School','Exchange','Grant','Course','Bootcamp','Mentorship','Award','Incubator','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Eligible country</label><input class="input" name="country" placeholder="e.g. Ethiopia or Global"></div><div class="field"><label>Age</label><input class="input" type="number" min="0" max="120" name="age" placeholder="Your age"></div><div class="field"><label>Education level / grade</label><input class="input" name="grade" placeholder="e.g. Grade 10, undergraduate"></div><div class="field"><label>Funding</label><select class="select" name="funding"><option>All funding</option>${['Fully funded','Partially funded','Tuition only','Stipend','Fee-based','No fee','Unfunded','Not stated'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Study / delivery mode</label><select class="select" name="modality"><option>Any mode</option>${['Online','In person','Hybrid','Self-paced','Not stated'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Record status</label><select class="select" name="status"><option>All records</option><option>verified</option><option>pending_review</option><option>expired</option><option>closed</option><option>needs_update</option></select></div><div class="field"><label>Deadline type</label><select class="select" name="deadlineType"><option>Any deadline</option><option>Fixed</option><option>Rolling</option><option>Not stated</option></select></div></div><div class="row"><button class="btn btn-primary">Apply filters</button><button type="reset" class="btn btn-light">Clear filters</button></div></form>
 <div class="catalogue-toolbar"><div><h2 class="subhead">Opportunity catalogue</h2><p class="subtext" id="count"></p></div><div class="row"><button class="btn btn-outline btn-sm" data-act="toggle-add">+ Add one listing</button><button class="btn btn-outline btn-sm" data-act="import-catalogue">Import CSV / JSON</button><button class="btn btn-light btn-sm" data-act="export-catalogue">Export catalogue</button><input id="catalogueFile" type="file" accept=".csv,.json,text/csv,application/json" hidden></div></div>
 <div id="opList" class="grid2" style="margin-top:14px"></div>
 <section class="panel hide" id="addPanel" style="margin-top:20px"><h2 class="subhead">Add a source-linked listing</h2><p class="subtext">This record is local to this browser. A real database and moderator review are required before it can appear to other users as an official catalogue entry.</p><form id="addForm"><div class="fieldrow"><div class="field"><label>Opportunity name *</label><input class="input" name="title" required></div><div class="field"><label>Provider / organizer *</label><input class="input" name="provider" required></div></div><div class="fieldrow"><div class="field"><label>Category *</label><select class="select" name="category">${['Scholarship','Competition','Research','Fellowship','Internship','Apprenticeship','Volunteering','Conference','Youth Program','Summer School','Exchange','Grant','Course','Bootcamp','Mentorship','Award','Incubator','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Official HTTPS URL *</label><input class="input" type="url" name="url" required placeholder="https://..."></div></div><div class="field"><label>Description *</label><textarea class="textarea" name="description" required></textarea></div><div class="fieldrow"><div class="field"><label>Minimum age</label><input class="input" type="number" name="min" min="0"></div><div class="field"><label>Maximum age</label><input class="input" type="number" name="max" min="0"></div><div class="field"><label>Eligible countries (semicolon separated)</label><input class="input" name="countries" placeholder="Worldwide or Ethiopia; Kenya"></div></div><div class="fieldrow"><div class="field"><label>Education levels / grades</label><input class="input" name="grades" placeholder="Grade 9; Grade 10; Undergraduate"></div><div class="field"><label>Subjects / fields</label><input class="input" name="subjects" placeholder="STEM; Arts; Leadership"></div></div><div class="fieldrow"><div class="field"><label>Funding type</label><select class="select" name="funding"><option>Not stated</option><option>Fully funded</option><option>Partially funded</option><option>Tuition only</option><option>Stipend</option><option>Fee-based</option><option>No fee</option><option>Unfunded</option></select></div><div class="field"><label>Delivery mode</label><select class="select" name="modality"><option>Not stated</option><option>Online</option><option>In person</option><option>Hybrid</option><option>Self-paced</option></select></div><div class="field"><label>Deadline (ISO date or stated text)</label><input class="input" name="deadline" placeholder="2027-01-31 or Rolling"></div></div><div class="fieldrow"><div class="field"><label>Last checked (optional)</label><input class="input" type="date" name="checked"></div><div class="field"><label>Reviewer role (optional)</label><input class="input" name="verifiedBy" placeholder="e.g. catalogue editor"></div></div><div class="notice info">New listings enter <b>Pending review</b>. A browser-only form cannot grant an official verification badge. An authorized reviewer must check the provider's source before publication.</div><div class="row"><button class="btn btn-primary">Save listing locally</button><button type="button" class="btn btn-light" data-act="toggle-add">Cancel</button></div></form></section>
 <section class="catalogue-coverage"><div><span class="eyebrow">BUILT FOR GLOBAL FILTERING</span><h3>One record. Many ways to find it.</h3><p>Opportunity data can be classified by age, eligible nationality or residence, region, education level, subject, delivery mode, funding, fee, deadline, language and required documents.</p></div><div class="coverage-tags"><span>Age range</span><span>Country</span><span>Education</span><span>Funding</span><span>Online / in-person</span><span>Deadline</span><span>Language</span><span>Documents</span></div></section></div>`;filterOps();}
function filterOps(){const f=document.getElementById('filters');if(!f)return;const d=new FormData(f),q=normKey(d.get('q')),cat=d.get('cat'),country=normKey(d.get('country')),age=d.get('age')?Number(d.get('age')):null,grade=normKey(d.get('grade')),funding=d.get('funding'),modality=d.get('modality'),status=d.get('status'),deadlineType=d.get('deadlineType');
 const matchesCountry=o=>!country||(!(o.excludedCountries||[]).some(c=>normKey(c)===country)&&((o.countries||[]).some(c=>['worldwide','global','international','all countries','any country'].includes(normKey(c))||normKey(c).includes(country))||(o.regions||[]).some(r=>normKey(r).includes(country))));
 const list=allOpp().filter(o=>(!q||normKey([o.title,o.provider,o.description,o.category,(o.subjects||[]).join(' '),(o.regions||[]).join(' ')].join(' ')).includes(q))&&(cat==='All categories'||o.category===cat)&&matchesCountry(o)&&(age===null||((o.minAge!==null||o.maxAge!==null)&&(o.minAge==null||age>=Number(o.minAge))&&(o.maxAge==null||age<=Number(o.maxAge))))&&(!grade||((o.grades||[]).length>0&&((o.grades||[]).some(x=>normKey(x).includes(grade))||['worldwide','all levels','any level'].some(x=>(o.grades||[]).map(normKey).includes(x)))))&&(funding==='All funding'||normKey(o.funding).includes(normKey(funding)))&&(modality==='Any mode'||normKey(o.modality).includes(normKey(modality)))&&(status==='All records'||(o.verificationStatus||'pending_review')===status)&&(deadlineType==='Any deadline'||normKey(o.deadlineType).startsWith(normKey(deadlineType))));
 document.getElementById('opList').innerHTML=list.length?list.map(cardOpp).join(''):'<div class="empty" style="grid-column:1/-1"><b>No catalogue records match these filters.</b>Import a verified dataset or broaden your search. The current prototype has no live worldwide feed connected.</div>';
 const verified=list.filter(o=>o.verificationStatus==='verified').length;document.getElementById('count').textContent=`${list.length} records shown · ${verified} source-checked · ${state.custom.length} imported / locally added in this browser · ${OD_DATA.opportunities.length} initial directory seeds`;
}
function score(o,p){
 const countries=o.countries||[], excluded=(o.excludedCountries||[]).some(c=>normKey(c)===normKey(p.country));
 const countryAliases=['worldwide','global','international','all countries','any country','open globally'];
 const countryKnown=countries.length>0||excluded;
 const country= !countryKnown?'unknown':(excluded?'mismatch':(countries.some(c=>countryAliases.includes(normKey(c))||normKey(c)===normKey(p.country)||normKey(c).includes(normKey(p.country)))||false?'match':'mismatch'));
 const ageKnown=o.minAge!=null||o.maxAge!=null;
 const age=!ageKnown?'unknown':((o.minAge==null||Number(p.age)>=Number(o.minAge))&&(o.maxAge==null||Number(p.age)<=Number(o.maxAge))?'match':'mismatch');
 const gradeValues=(o.grades||[]).map(normKey).filter(Boolean), studentGrade=normKey(p.grade);
 const broadSchoolLabels=['high school','secondary school','secondary education','upper secondary','high-school students','secondary students'];
 const grade= !gradeValues.length?'unknown':(gradeValues.some(x=>x===studentGrade||x.includes(studentGrade)||studentGrade.includes(x)||((broadSchoolLabels.includes(x)||broadSchoolLabels.some(y=>x.includes(y)))&&/(grade|class|year)\s*(9|10|11|12)|high school|secondary/i.test(studentGrade)))?'match':'mismatch');
 const subjects=o.subjects||[], interests=Array.isArray(p.interests)?p.interests:[];
 const sub=!subjects.length||!interests.length?'unknown':(subjects.some(x=>normKey(x)==='any subject'||interests.some(y=>normKey(x).includes(normKey(y))||normKey(y).includes(normKey(x))))?'match':'mismatch');
 const core=[country,age,grade], matches=core.filter(x=>x==='match').length, mismatches=core.filter(x=>x==='mismatch').length, unknowns=core.filter(x=>x==='unknown').length;
 const verified=o.verificationStatus==='verified';
 let outcome;
 if(mismatches) outcome='Conflicts with one or more recorded requirements';
 else if(unknowns) outcome='Needs manual eligibility verification';
 else if(verified) outcome='Potential fit based on recorded core criteria; confirm with the provider';
 else outcome='Recorded core criteria appear to fit, but this listing is not verified';
 return {country,age,grade,sub,matches,mismatches,unknowns,verified,outcome,coreComplete:unknowns===0};
}
function runMatcher(p){
 const target=document.getElementById('matches');
 if(!target)return;
 if(!p.country||!p.age||!p.grade){target.innerHTML='<div class="empty" style="grid-column:1/-1"><b>Add your basic profile details first.</b>Enter country, age and education level to compare them with recorded requirements.</div>';return;}
 const found=allOpp().map(o=>({o,s:score(o,p)})).sort((a,b)=>Number(b.s.verified)-Number(a.s.verified)||b.s.matches-a.s.matches||a.s.mismatches-b.s.mismatches||a.o.title.localeCompare(b.o.title));
 target.innerHTML=found.length?found.map(({o,s})=>{
  const label=s.mismatches?'Criteria conflict':s.unknowns?'Needs verification':s.verified?'Source checked':'Pending review';
  const tag=s.mismatches?'warn':s.verified&&s.coreComplete?'good':'demo';
  const detail=(key)=>s[key]==='match'?'Matches recorded rule':s[key]==='mismatch'?'Conflicts with recorded rule':'Not stated; check manually';
  return `<article class="card"><div class="opp-card-tags"><span class="tag ${tag}">${label}</span><span class="tag">${s.matches}/3 core criteria match</span></div><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p><div class="details"><div><b>Country</b>${detail('country')}</div><div><b>Age</b>${detail('age')}</div><div><b>Education</b>${detail('grade')}</div><div><b>Interest alignment</b>${s.sub==='match'?'Relevant recorded subject':s.sub==='mismatch'?'No recorded overlap':'Not enough information'}</div></div><p class="small"><b>${esc(s.outcome)}.</b> Matching is a preliminary comparison, not an official eligibility decision or selection prediction. Always confirm current requirements on the organizer's official page.</p><div class="row"><button class="btn btn-primary btn-sm" data-act="save" data-id="${esc(o.id)}">${state.saved.includes(o.id)?'Saved ✓':'Save opportunity'}</button>${o.url?`<a class="text-link" href="${esc(o.url)}" target="_blank" rel="noopener">Check provider ↗</a>`:''}</div></article>`;
 }).join(''):'<div class="empty" style="grid-column:1/-1"><b>No opportunity records have been imported.</b>Import a catalogue first, then run the comparison again.</div>';
}
function matcher(){const p=state.profile;document.getElementById('view').innerHTML=`<div class="page">${intro('SMART MATCHER','See which requirements may fit your profile.','A transparent rules-based comparison of your profile with requirements recorded in the opportunity listing. It does not determine official eligibility or predict acceptance.')}<div class="notice info">No personal profile is sent to a server. Use only basic matching details. Do not enter identity numbers, passport details or sensitive information.</div><div class="grid2"><section class="panel"><h2 class="subhead">Your student profile</h2><p class="subtext">You can use a fictional profile to test the matcher.</p><form id="matchForm"><div class="fieldrow"><div class="field"><label>Country</label><input class="input" name="country" value="${esc(p.country)}" placeholder="Enter your country" required></div><div class="field"><label>Age</label><input class="input" type="number" min="10" max="100" name="age" value="${esc(p.age)}" placeholder="Age" required></div></div><div class="field"><label>Education level</label><input class="input" name="grade" value="${esc(p.grade)}" placeholder="e.g. Grade 10, undergraduate" required></div><div class="field"><label>Interests</label><div class="tabs">${['Computer Science','Mathematics','STEM','Science','Research','Writing','Leadership','Community Service','Programming','Arts','Business','Environment','Health','Humanities','Languages','Any Subject'].map(x=>`<label class="tab ${p.interests.includes(x)?'active':''}"><input type="checkbox" name="interests" value="${x}" ${p.interests.includes(x)?'checked':''}> ${x}</label>`).join('')}</div></div><button class="btn btn-primary">Find potential matches →</button></form></section><aside class="panel"><div class="mini">HOW MATCHING WORKS</div><h2 class="subhead">Transparent by design</h2><p class="small">The first version checks:</p><ul class="small"><li>Country / location</li><li>Age range</li><li>Education level</li><li>Subject or interest relevance</li></ul><div class="notice info">A match only means the saved criteria appear to fit. Organizers make final eligibility and selection decisions. Missing information requires manual checking.</div></aside></div><div style="margin-top:25px"><h2 class="subhead">Potential matches</h2><p class="subtext">Results from the records currently stored in this browser.</p><div id="matches" class="grid2"></div></div></div>`;runMatcher(p);}
function academy(){const tracks=['All',...new Set(OD_DATA.academy.map(c=>c.track))],items=OD_DATA.academy.filter(c=>track==='All'||c.track===track);document.getElementById('view').innerHTML=`<div class="page">${intro('STUDENT DEVELOPMENT ACADEMY','Build skills for study, work and life.','Structured lessons, real exercises and knowledge checks. Learn at your own pace and record progress in this browser.')}<div class="notice info">These materials provide general educational guidance. They are not professional financial, legal or medical advice. Adapt activities to your circumstances and seek qualified support when needed.</div><div class="tabs">${tracks.map(t=>`<button class="tab ${track===t?'active':''}" data-act="track-filter" data-track="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="grid3">${items.map(c=>`<article class="card" data-act="open-course" data-course="${c.id}" style="cursor:pointer"><div class="mini">${esc(c.track)}</div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><div class="row"><span class="tag">${c.level}</span><span class="tag purple-tag">${c.time}</span></div><div class="row"><span class="small">${c.lessons.length} lessons · ${c.lessons.filter((l,i)=>state.completed.includes(c.id+':'+i)).length}/${c.lessons.length} complete</span><span class="text-link">Open →</span></div></article>`).join('')}</div>${courseOpen?courseDetail(courseOpen):''}</div>`;}
function courseDetail(id){const c=OD_DATA.academy.find(x=>x.id===id);if(!c)return '';return `<section class="panel" id="courseDetail" style="margin-top:20px"><div class="mini">${esc(c.track)} · ${c.level} · ${c.time}</div><h2 class="subhead" style="margin-top:8px">${esc(c.title)}</h2><p class="subtext">${esc(c.summary)}</p>${c.lessons.map((l,i)=>{const key=c.id+':'+i,done=state.completed.includes(key);return `<article class="lesson"><div class="row"><h3>${i+1}. ${esc(l.title)}</h3><span class="tag ${done?'good':''}">${done?'Completed':'Lesson'}</span></div>${l.body.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="task"><b>Practical exercise:</b> ${esc(l.task)}</div><button class="btn ${done?'btn-light':'btn-primary'} btn-sm" data-act="complete" data-course="${c.id}" data-lesson="${i}">${done?'Mark incomplete':'Mark lesson complete'}</button></article>`;}).join('')}<div class="quiz"><div class="mini">KNOWLEDGE CHECK</div><h3>Check what you learned</h3>${c.quiz.map((q,i)=>`<div style="margin:14px 0"><b class="small">${i+1}. ${esc(q.q)}</b>${q.options.map((o,j)=>`<button data-act="answer" data-course="${c.id}" data-q="${i}" data-choice="${j}">${String.fromCharCode(65+j)}. ${esc(o)}</button>`).join('')}<div class="quiz-feedback" id="feedback-${c.id}-${i}"></div></div>`).join('')}</div></section>`;}
function prepare(){document.getElementById('view').innerHTML=`<div class="page">${intro('PREPARE & APPLY','Turn your experience into a clear application.','Practical guidance for presenting your work honestly, organizing documents and communicating with program providers.')}<div class="grid2"><section class="panel"><div class="mini">01 · CV</div><h2 class="subhead">Build a student CV</h2><p class="small">Include relevant education, projects, volunteering, competitions, skills and languages. Keep it readable and truthful. A short CV is acceptable at an early stage.</p><ol class="small"><li>Education and relevant subjects.</li><li>Projects and your actual contribution.</li><li>Volunteering and leadership.</li><li>Competitions and awards.</li><li>Demonstrable skills.</li></ol><p class="notice info">Do not invent experience or include sensitive details that are not required.</p><button class="btn btn-outline btn-sm" data-act="copy" data-template="cv">Copy CV outline</button></section><section class="panel"><div class="mini">02 · PERSONAL STATEMENT</div><h2 class="subhead">Write with evidence</h2><p class="small">Explain why the opportunity matters, which real experience shaped your interest, what you did, what you learned and how you hope to contribute.</p><ol class="small"><li>Start with genuine motivation.</li><li>Describe an experience or project.</li><li>Explain what you learned.</li><li>Connect your interests to the program.</li><li>Follow its word limit and instructions.</li></ol><button class="btn btn-outline btn-sm" data-act="copy" data-template="essay">Copy statement planner</button></section><section class="panel"><div class="mini">03 · RECOMMENDATIONS</div><h2 class="subhead">Ask early and respectfully</h2><p class="small">Share the program, deadline, submission method, CV and a concise summary of your work. Ask whether the person is comfortable recommending you. Do not assume they can.</p><button class="btn btn-outline btn-sm" data-act="copy" data-template="recommendation">Copy request outline</button></section><section class="panel"><div class="mini">04 · INTERVIEWS</div><h2 class="subhead">Prepare real examples</h2><p class="small">Use STAR: Situation, Task, Action and Result. Prepare examples about a project, teamwork, motivation and a challenge. If you do not know an answer, be honest.</p><button class="btn btn-outline btn-sm" data-act="copy" data-template="interview">Copy interview practice sheet</button></section><section class="panel"><div class="mini">05 · PROFESSIONAL EMAIL</div><h2 class="subhead">Write one clear message</h2><div class="template" id="emailText">Subject: Question about [Program Name] eligibility\n\nDear [Program Team],\n\nMy name is [Name], and I am a [grade / education level] student from [country]. I am reviewing the official information for [Program Name] and would like to clarify: [specific question].\n\nI checked [page or requirement], but I am still unsure about [detail]. Could you please confirm [request]?\n\nThank you for your time.\nKind regards,\n[Name]</div><button class="btn btn-outline btn-sm" data-act="copy" data-template="email">Copy email template</button></section><section class="panel"><div class="mini">06 · BEFORE SUBMITTING</div><h2 class="subhead">Application checklist</h2>${['I checked age, grade and country eligibility.','I checked exactly what funding covers.','I confirmed the deadline and time zone.','I prepared every required document.','I checked spelling, file formats and links.','I saved proof of submission.'].map(x=>`<label class="checkline"><input type="checkbox"> ${x}</label>`).join('')}<p class="small">Use the provider’s official checklist if it differs from this general guide.</p></section></div></div>`;}
function dashboard(){const saved=allOpp().filter(o=>state.saved.includes(o.id)),total=OD_DATA.academy.reduce((n,c)=>n+c.lessons.length,0),pct=Math.round(state.completed.length/total*100);document.getElementById('view').innerHTML=`<div class="page">${intro('MY STUDENT SPACE','Your plans, progress and next steps.','You can use this student workspace without signing in. Local progress stays in this browser; optional passwordless accounts require the backend to be connected.')}<div class="notice info">Shared device? Do not store sensitive information here. Export a backup and clear local data before another person uses the browser.</div><div class="grid4" style="margin:18px 0"><div class="stats"><b>${saved.length}</b><span>Saved opportunities</span></div><div class="stats"><b>${state.applications.length}</b><span>Tracked applications</span></div><div class="stats"><b>${state.completed.length}</b><span>Lessons completed</span></div><div class="stats"><b>${state.tasks.filter(t=>!t.done).length}</b><span>Open planner tasks</span></div></div><div class="grid2"><section class="panel"><h2 class="subhead">Learning progress</h2><p class="subtext">${state.completed.length} of ${total} lessons marked complete · ${pct}%</p><div class="progress"><span style="width:${pct}%"></span></div><div class="row"><span class="small">Continue learning</span><a class="text-link" href="#academy">Open Academy →</a></div><h2 class="subhead" style="margin-top:22px">Saved opportunities</h2>${saved.length?saved.map(o=>`<div class="listrow"><div><b>${esc(o.title)}</b><small>${esc(o.category)} · ${o.demo?'Fictional demo':'Local record; verify source'}</small></div><button class="btn btn-light btn-sm" data-act="track" data-id="${o.id}">Track</button></div>`).join(''):'<div class="empty"><b>No saved opportunities</b>Browse and save listings to review later.</div>'}</section><section class="panel"><h2 class="subhead">My student profile</h2><p class="subtext">Only enter basic details needed for matching.</p><form id="profileForm"><div class="field"><label>Country</label><input class="input" name="country" value="${esc(state.profile.country)}"></div><div class="fieldrow"><div class="field"><label>Age</label><input class="input" name="age" type="number" min="10" max="100" value="${esc(state.profile.age)}"></div><div class="field"><label>Grade / level</label><input class="input" name="grade" value="${esc(state.profile.grade)}"></div></div><div class="field"><label>Interests separated by commas</label><input class="input" name="interests" value="${esc(state.profile.interests.join(', '))}"></div><button class="btn btn-primary btn-sm">Save locally</button></form><p class="small">Local storage is not a secure account or cloud backup.</p></section></div><div class="grid2" style="margin-top:15px"><section class="panel"><h2 class="subhead">Application tracker</h2>${state.applications.length?state.applications.map(a=>`<div class="listrow"><div><b>${esc(a.title)}</b><small>${esc(a.category)}</small></div><select class="select" style="max-width:145px" data-status="${esc(a.id)}">${['Considering','Preparing','Submitted','Accepted','Rejected','Withdrawn'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></div>`).join(''):'<div class="empty"><b>No applications tracked</b>Save an opportunity and choose Track application.</div>'}</section><section class="panel"><h2 class="subhead">Study and action planner</h2><form id="taskForm"><div class="field"><label>Task</label><input class="input" name="title" required placeholder="e.g. Finish CV draft"></div><div class="fieldrow"><div class="field"><label>Due date</label><input class="input" type="date" name="due"></div><div class="field"><label>Category</label><select class="select" name="category"><option>Study</option><option>Application</option><option>Project</option><option>Personal</option></select></div></div><button class="btn btn-primary btn-sm">+ Add task</button></form>${state.tasks.map(t=>`<div class="listrow"><label class="checkline"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><span><b>${esc(t.title)}</b><small>${esc(t.category)} · ${esc(t.due||'No due date')}</small></span></label><button class="btn btn-light btn-sm" data-act="delete-task" data-id="${t.id}">Remove</button></div>`).join('')}</section></div><section class="panel" style="margin-top:15px"><h2 class="subhead">Data controls</h2><p class="subtext">Export a backup or clear data saved in this browser. Clearing cannot be undone without a backup.</p><div class="row"><button class="btn btn-outline btn-sm" data-act="export">Export JSON backup</button><button class="btn btn-outline btn-sm" data-act="import">Import backup</button><button class="btn btn-danger btn-sm" data-act="clear">Clear local data</button></div></section></div>`;}
function resources(){document.getElementById('view').innerHTML=`<div class="page">${intro('RESOURCE LIBRARY','Useful places to keep learning.','A starting collection of free or openly accessible resources. Availability, account requirements and regional access can vary; check each provider.')}<div class="toolbar"><div class="field" style="flex:2"><label>Search resources</label><input class="input" id="resourceSearch" placeholder="Search subject or provider"></div><div class="field"><label>Category</label><select class="select" id="resourceCat"><option>All categories</option>${[...new Set(OD_DATA.resources.map(r=>r.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></div></div><div class="grid3" id="resourceList"></div><div class="notice info" style="margin-top:18px">OpenDoor does not control external sites, regional access, policies or availability. Review provider terms and privacy information.</div></div>`;filterResources();}
function filterResources(){const q=(document.getElementById('resourceSearch')?.value||'').toLowerCase(),cat=document.getElementById('resourceCat')?.value||'All categories';const list=OD_DATA.resources.filter(r=>(cat==='All categories'||r.category===cat)&&[r.title,r.category,r.description].join(' ').toLowerCase().includes(q));document.getElementById('resourceList').innerHTML=list.map(r=>`<article class="card"><div class="mini">${esc(r.category)}</div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><a class="text-link" href="${esc(r.url)}" target="_blank" rel="noopener">Visit resource ↗</a></article>`).join('');}
function dataSources(){const info=OD_DATA.datasetInfo||{};const sources=OD_DATA.sources||[];const seedCount=(OD_DATA.opportunities||[]).length;document.getElementById('view').innerHTML=`<div class="page">${intro('DATA, SOURCES & COVERAGE','A catalogue that grows through evidence, not guesses.','Explore the initial provider directory, inspect dataset provenance and learn how OpenDoor classifies, imports and verifies opportunity information.')}<div class="grid3"><article class="metric-card"><div class="mini">PROGRAM DIRECTORY SEEDS</div><strong>${seedCount}</strong><p>Discovery leads, not confirmed open applications.</p></article><article class="metric-card"><div class="mini">STUDENT SAMPLE DATA</div><strong>${info.studentProgramRows||500}</strong><p>Separate sample records for schema testing and demonstration analytics.</p></article><article class="metric-card"><div class="mini">SOURCE REGISTRY</div><strong>${sources.length}</strong><p>Provider and dataset sources listed for review.</p></article></div><section class="panel" style="margin-top:18px"><div class="row space-between"><div><div class="mini">GLOBAL PROGRAM DIRECTORY</div><h2 class="subhead">Programs and providers to investigate</h2><p class="subtext">Every item below is a discovery lead. Current cycles, deadlines, costs, funding and exact eligibility have not been checked in this release.</p></div><a class="btn btn-outline btn-sm" href="#opportunities">Explore catalogue →</a></div><div class="grid2" style="margin-top:15px">${(OD_DATA.opportunities||[]).map(o=>`<article class="feedback-card"><div class="row"><b>${esc(o.title)}</b><span class="tag warn">Review needed</span></div><p>${esc(o.description)}</p><small>${esc(o.provider)} · ${esc(o.category)} · <a href="${esc(o.url)}" target="_blank" rel="noopener">Source page ↗</a></small></article>`).join('')}</div></section><section class="grid2" style="margin-top:18px"><article class="panel"><div class="mini">USER-PROVIDED DATASET</div><h2 class="subhead">Student program sample</h2><div class="details"><div><b>Rows</b>${info.studentProgramRows||500}</div><div><b>Columns</b>${info.studentProgramColumns||10}</div><div><b>Age values</b>${(info.studentProgramAgeRange||[16,25]).join('–')}</div><div><b>Missing cells</b>0 in supplied file</div></div><p class="small">Fields include age, gender, prior education, attendance rate, test score, family-income band, distance to school, parent engagement and program completion. It does not contain opportunity names, official links, application dates or eligibility rules.</p><div class="notice info">Treat this as sample/generated data until its provenance and license are confirmed. It is not used for opportunity matching or claims about real students.</div><a class="text-link" href="datasets/student_program_data_profile.json" target="_blank">View aggregate dataset profile ↗</a></article><article class="panel"><div class="mini">DATASET DISCOVERY SOURCES</div><h2 class="subhead">Bring in more structured data</h2><p class="small"><b>EvalCommunity:</b> the student-program dataset generator supplied for this project. Use its output as sample data unless provenance says otherwise.</p><a class="text-link" href="https://academy.evalcommunity.com/tools/student-program-dataset-generator/" target="_blank" rel="noopener">Open EvalCommunity generator ↗</a><p class="small" style="margin-top:14px"><b>Kaggle:</b> a dataset discovery directory. Choose an exact dataset, check its license and provenance, and map only appropriate records. A Kaggle dataset is not automatically an official opportunity source.</p><a class="text-link" href="https://www.kaggle.com/datasets" target="_blank" rel="noopener">Browse Kaggle datasets ↗</a><div class="notice warn" style="margin-top:14px">Never put API tokens or passwords in this public website or a shared notebook.</div></article></section><section class="panel" style="margin-top:18px"><div class="mini">SOURCE REGISTRY</div><h2 class="subhead">Provider sources and discovery portals</h2><p class="subtext">These are starting points only. “Needs review” means OpenDoor has not checked the current opportunity cycle or source terms.</p><div class="source-list">${sources.map(s=>`<div class="source-row"><div><b>${esc(s.name)}</b><small>${esc(s.kind)} · ${esc(s.scope)}</small></div><span class="tag warn">${esc(s.status)}</span>${s.url?`<a class="text-link" href="${esc(s.url)}" target="_blank" rel="noopener">Open ↗</a>`:'<small>Official URL not confirmed</small>'}</div>`).join('')}</div></section><section class="panel" style="margin-top:18px"><div class="mini">AUTOMATED COLLECTION</div><h2 class="subhead">How the catalogue can update</h2><ol class="small"><li>Register only official provider sites, public APIs or permitted RSS/Atom feeds.</li><li>Fetch announcements at a controlled interval with source terms and rate limits respected.</li><li>Normalize titles, categories, countries, age, grade, funding, deadline, mode and source URL.</li><li>Deduplicate records and flag expired or changed deadlines.</li><li>Send new or changed records to a human review queue.</li><li>Publish only records whose official details have been checked.</li></ol><p class="small">The project includes a feed collector and catalogue validator in the datasets folder. No global feed sync is running in this static prototype; configure approved feed URLs and run the Colab workflow to collect candidates.</p><div class="row"><a class="btn btn-outline btn-sm" href="datasets/README.md" target="_blank">Data workflow guide</a><a class="btn btn-outline btn-sm" href="datasets/source_registry.csv" download>Download source registry</a><a class="btn btn-outline btn-sm" href="datasets/global_opportunities_seed.csv" download>Download seed catalogue</a></div></section></div>`;}

function about(){document.getElementById('view').innerHTML=`<div class="page">${intro('ABOUT OPENDOOR','A clearer route from discovery to action.','OpenDoor is a student opportunity and development platform concept. It brings opportunity discovery, eligibility guidance, learning resources and preparation tools into one place.')}<div class="grid2"><section class="panel"><div class="mini">OUR PURPOSE</div><h2 class="subhead">Make the next step easier to understand.</h2><p class="small">Help learners discover educational and development opportunities, understand their requirements, build useful skills and plan informed next steps.</p></section><section class="panel"><div class="mini">OUR APPROACH</div><h2 class="subhead">Discover. Develop. Prepare. Act.</h2><p class="small">A connected workspace that supports opportunity search, transparent matching, structured learning and application preparation.</p></section><section class="panel"><div class="mini">CURRENT BUILD STATUS</div><h2 class="subhead">Prototype with local data tools</h2><p class="small">This release includes an opportunity discovery catalogue, local data tools, an optional Supabase backend integration, passwordless email-code sign-in, moderated feedback, AI assistant endpoint, and hosted-checkout integration code. These services are not live until an administrator deploys and configures them.</p></section><section class="panel"><div class="mini">OUR DATA STANDARD</div><h2 class="subhead">Accuracy before volume.</h2><ul class="small"><li>Prefer official provider pages and feeds.</li><li>Show eligibility, funding, deadline and last-checked date.</li><li>Separate verified, pending-review and expired records.</li><li>Never guarantee eligibility, admission or funding.</li><li>Keep personal data collection minimal.</li></ul></section></div><section class="panel" style="margin-top:15px"><h2 class="subhead">Privacy and local storage</h2><p class="small">The local workspace does not require sign-in. Optional passwordless email accounts are available only after the backend is configured. Local profile details, saved opportunities, learning progress and tasks stay in the current browser. They are not synchronized to a server or visible to other users. Do not enter passwords, identity numbers, passport details, financial details or other sensitive information. On a shared device, export only what you need and clear local data when finished.</p></section><section class="panel" style="margin-top:15px"><h2 class="subhead">What is needed for the full platform?</h2><p class="small">A production service needs a secure database, official-source integrations, scheduled data refresh jobs, human review for uncertain listings, account security, consent and privacy controls, moderation for public comments, and a real payment provider for optional premium services.</p><a class="text-link" href="#feedback">Share product feedback →</a></section></div>`;}
function plans(){document.getElementById('view').innerHTML=`<div class="page">${intro('PLANS','Core access for everyone. Advanced support as an option.','Opportunity information should be accessible. A paid tier may add convenience and deeper support, but it must never imply guaranteed admission or better treatment by a program organizer.')}<div class="notice info"><b>Prototype status:</b> Premium is a proposed plan only. No checkout, billing, subscriptions or account entitlements are active. Prices will be set only after costs and student affordability are tested.</div><div class="pricing-grid"><article class="pricing-card"><div class="pricing-top"><span class="plan-label">FREE</span><span class="plan-price">$0 <small>/ always</small></span><p>Essential access for every student.</p></div><ul><li>Browse and search the public opportunity directory</li><li>Country, age, grade, funding and category filters</li><li>Basic explainable matching</li><li>Core Student Academy lessons</li><li>Basic CV, essay and email templates</li><li>Local application tracker and study planner</li><li>Official source links and verification labels</li></ul><span class="plan-state available">Included in this prototype</span></article><article class="pricing-card premium"><div class="pricing-top"><span class="plan-label">PREMIUM · PROPOSED</span><span class="plan-price">Price to be tested</span><p>Optional advanced tools for students who want more structure.</p></div><ul><li>Saved searches and advanced match explanations</li><li>Custom deadline digests and reminders</li><li>Expanded CV and application export packs</li><li>Advanced study plans and progress insights</li><li>Guided application preparation workflows</li><li>Cloud sync after secure accounts are implemented</li><li>Optional AI assistance with source and accuracy checks</li></ul><button class="btn btn-primary od-premium-button" type="button" data-backend-act="upgrade">Continue to Premium · backend required</button><span class="plan-state planned">Checkout remains locked until adult/guardian authorization and legal setup are complete.</span></article></div><section class="panel plan-policy"><h2 class="subhead">Access, safety and pricing principles</h2><p class="small">Essential opportunity facts, official links and basic eligibility criteria remain free. Premium benefits and prices must be clearly stated before purchase. No paid feature can guarantee admission, a scholarship or privileged treatment by an organizer. Cloud sync and paid access require secure accounts and a real payment backend. Since many users are minors, purchases remain disabled until an appropriate adult/guardian-controlled billing arrangement and legal review are completed. OpenDoor does not currently accept payments in this build.</p></section></div>`;}

function feedbackPage(){const items=[...(state.feedback||[])].slice().reverse();document.getElementById('view').innerHTML=`<div class="page">${intro('COMMUNITY FEEDBACK','Help improve how OpenDoor works.','Share a suggestion, report a problem or describe which part of the platform is useful. Keep feedback respectful and do not include private information.')}<div class="notice info"><b>Moderation:</b> When the backend is connected, submissions enter a pending queue and appear publicly only after moderator approval. Without backend configuration, feedback remains a private local preview.</div><div class="grid2 feedback-layout"><section class="panel"><h2 class="subhead">Leave feedback</h2><form id="communityFeedbackForm"><div class="field"><label>What are you commenting on?</label><select class="select" name="topic"><option>Overall experience</option><option>Opportunity explorer</option><option>Smart Matcher</option><option>Student Academy</option><option>Preparation tools</option><option>Accessibility and design</option><option>Bug or incorrect information</option></select></div><div class="field"><label>Rating</label><select class="select" name="rating"><option value="5">5 · Excellent</option><option value="4">4 · Good</option><option value="3" selected>3 · Okay</option><option value="2">2 · Needs work</option><option value="1">1 · Poor</option></select></div><div class="field"><label>Your comment *</label><textarea class="textarea" name="comment" minlength="8" maxlength="700" required placeholder="What worked? What was confusing? What should change?"></textarea><small class="small">8–700 characters. Do not include names, phone numbers, addresses or other personal details.</small></div><button class="btn btn-primary">Submit feedback</button></form></section><section class="panel"><div class="mini">FEEDBACK PREVIEW</div><h2 class="subhead">Local feedback preview</h2><p class="subtext">Local preview entries are private. Public reviews are fetched only after moderator approval when the backend is connected.</p><div id="feedbackList">${items.length?items.map(feedbackCard).join(''):'<div class="empty"><b>No feedback added yet.</b>Be the first to test the feedback form on this device.</div>'}</div></section></div></div>`;}
function feedbackCard(x){return `<article class="feedback-card"><div class="row"><b>${esc(x.topic||'OpenDoor feedback')}</b><span class="feedback-stars">${'★'.repeat(Math.max(1,Math.min(5,Number(x.rating)||3)))}${'☆'.repeat(5-Math.max(1,Math.min(5,Number(x.rating)||3)))}</span></div><p>${esc(x.comment)}</p><small>Local preview · ${esc(x.date||'Just now')}</small></article>`;}

const templates={cv:`[FULL NAME]\n[Professional email] · [City, Country] · [Portfolio link]\n\nEDUCATION\nSchool / Institution — Grade or program — Dates\nRelevant subjects\n\nPROJECTS\nProject — Dates\n• Problem or purpose\n• Your contribution and tools\n• Output or evidence\n\nVOLUNTEERING & LEADERSHIP\nActivity — Role — Dates\n\nCOMPETITIONS & RECOGNITION\nName — Result — Date\n\nSKILLS\nOnly skills you can demonstrate.`,essay:`PERSONAL STATEMENT PLANNER\n1. What opportunity are you applying for, and why?\n2. Which real experience shaped your interest?\n3. What did you personally do?\n4. What did you learn?\n5. What would you contribute?\n6. What do you hope to learn next?\n\nUse specific examples and follow the official word limit.`,recommendation:`Subject: Recommendation request for [Program] — deadline [date]\n\nDear [Name],\nI am applying to [program] because [reason]. Would you feel comfortable providing a recommendation? The deadline is [date], and submission instructions are [details]. I can share the program information, CV and summary of my work. I understand if your schedule does not allow it. Thank you for considering my request.\n\n[Name]`,interview:`INTERVIEW PRACTICE\nQuestion: Tell us about a project.\nSituation: What was happening?\nTask: What were you responsible for?\nAction: What did you do?\nResult: What was produced or learned?\n\nAlso prepare real examples about motivation, teamwork and a challenge.`,email:`Subject: Question about [Program Name] eligibility\n\nDear [Program Team],\n\nMy name is [Name], and I am a [grade] student from [country]. I am reviewing the official information for [Program] and would like to clarify [question].\n\nThank you for your time.\nKind regards,\n[Name]`};
function downloadData(){const blob=new Blob([JSON.stringify({app:'OpenDoor',version:2,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='opendoor-data-backup.json';a.click();URL.revokeObjectURL(url);notify('Backup downloaded.');}
function clickAction(el){const a=el.dataset.act,id=el.dataset.id;if(a==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();notify('Saved items updated.');render();}else if(a==='track'){const o=allOpp().find(x=>x.id===id);if(o&&!state.applications.some(x=>x.id===id)){state.applications.push({id,title:o.title,category:o.category,status:'Considering'});save();notify('Added to application tracker.');}else notify('Already in tracker.');if(page==='dashboard')dashboard();}else if(a==='toggle-add')document.getElementById('addPanel')?.classList.toggle('hide');else if(a==='import-catalogue')document.getElementById('catalogueFile')?.click();else if(a==='export-catalogue')exportOpportunityCSV();else if(a==='track-filter'){track=el.dataset.track;courseOpen=null;academy();}else if(a==='open-course'){courseOpen=el.dataset.course;academy();document.getElementById('courseDetail')?.scrollIntoView({behavior:'smooth'});}else if(a==='complete'){const key=el.dataset.course+':'+el.dataset.lesson;state.completed=state.completed.includes(key)?state.completed.filter(x=>x!==key):[...state.completed,key];save();academy();notify('Learning progress updated.');}else if(a==='answer'){const c=OD_DATA.academy.find(x=>x.id===el.dataset.course),q=c.quiz[Number(el.dataset.q)],fb=document.getElementById(`feedback-${c.id}-${el.dataset.q}`),ok=Number(el.dataset.choice)===q.answer;fb.textContent=(ok?'Correct. ':'Not quite. ')+q.why;fb.style.color=ok?'#159b8d':'#aa5a40';}else if(a==='copy'){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(templates[el.dataset.template]||'').then(()=>notify('Template copied.')).catch(()=>notify('Clipboard is unavailable in this browser.'));}else notify('Clipboard access requires a secure browser context.');}else if(a==='delete-task'){state.tasks=state.tasks.filter(t=>t.id!==id);save();dashboard();}else if(a==='export')downloadData();else if(a==='import')document.getElementById('importFile').click();else if(a==='clear'&&confirm('Clear all OpenDoor data saved in this browser? Export a backup first if you need it.')){localStorage.removeItem(KEY);state=clone(emptyState);save();dashboard();notify('Local data cleared.');}}
document.addEventListener('click',e=>{const act=e.target.closest('[data-act]');if(act){clickAction(act);return;}const trackLink=e.target.closest('[data-track]');if(trackLink && trackLink.tagName==='A'){e.preventDefault();track=trackLink.dataset.track;courseOpen=null;navigate('academy');return;}const link=e.target.closest('a[href^="#"]');if(link){const p=link.getAttribute('href').slice(1);if(['home','opportunities','matcher','academy','prepare','dashboard','resources','data','about','plans','feedback'].includes(p)){e.preventDefault();navigate(p);}}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='filters'){filterOps();}else if(f.id==='matchForm'){state.profile={country:d.get('country'),age:d.get('age')?Number(d.get('age')):'',grade:d.get('grade'),interests:d.getAll('interests')};save();runMatch();}else if(f.id==='addForm'){const url=String(d.get('url')||'');if(!/^https:\/\//i.test(url)){notify('Use an HTTPS official source URL.');return;}const checked=String(d.get('checked')||'');const o=normaliseOpportunity({id:'local-'+Date.now(),title:d.get('title'),provider:d.get('provider'),category:d.get('category'),description:d.get('description'),official_url:url,min_age:d.get('min'),max_age:d.get('max'),eligible_countries:d.get('countries'),education_levels:d.get('grades'),subjects:d.get('subjects'),funding_type:d.get('funding'),modality:d.get('modality'),deadline:d.get('deadline'),last_checked:checked,verified_by:d.get('verifiedBy'),verification_status:'pending_review'},0);state.custom.push(o);save();opportunities();notify('Listing saved locally. Verify status before publication.');}else if(f.id==='profileForm'){state.profile={...state.profile,country:d.get('country'),age:d.get('age')?Number(d.get('age')):'',grade:d.get('grade'),interests:String(d.get('interests')||'').split(',').map(x=>x.trim()).filter(Boolean)};save();notify('Profile saved locally.');}else if(f.id==='taskForm'){state.tasks.push({id:'t'+Date.now(),title:d.get('title'),due:d.get('due'),category:d.get('category'),done:false});save();dashboard();notify('Task added.');}else if(f.id==='communityFeedbackForm'){state.feedback=state.feedback||[];state.feedback.push({topic:String(d.get('topic')),rating:Number(d.get('rating')),comment:String(d.get('comment')).trim(),date:new Date().toLocaleDateString()});save();feedbackPage();notify('Feedback saved in this browser only.');}});
function runMatch(){runMatcher(state.profile);}
document.addEventListener('change',e=>{if(e.target.id==='resourceCat')filterResources();if(e.target.dataset.status){const a=state.applications.find(x=>x.id===e.target.dataset.status);if(a){a.status=e.target.value;save();notify('Application status updated.');}}if(e.target.dataset.task){const t=state.tasks.find(x=>x.id===e.target.dataset.task);if(t){t.done=e.target.checked;save();dashboard();}}if(e.target.id==='catalogueFile'){const file=e.target.files?.[0];if(file)importOpportunityFile(file);e.target.value='';}if(e.target.id==='importFile'){} });
document.addEventListener('input',e=>{if(e.target.id==='resourceSearch')filterResources();if(e.target.closest('#filters'))filterOps();});
document.addEventListener('reset',e=>{if(e.target?.id==='filters')setTimeout(filterOps,0);});
document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('nav').classList.toggle('open'));
document.getElementById('importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const j=JSON.parse(await file.text()),s=j.state||j;if(!s.profile||!Array.isArray(s.saved))throw Error();state={...clone(emptyState),...s};save();notify('Backup imported.');dashboard();}catch{notify('Invalid OpenDoor backup file.');}e.target.value='';});
window.addEventListener('hashchange',()=>{const p=(location.hash||'#home').slice(1);if(p!==page){page=p;render();}});
if(!location.hash)history.replaceState(null,'','#home');render();
